pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";

/// @notice Wallet-domain consent and signer-scoped revocation for full-amount releases.
/// @dev Derived wallets must use this same guard around observation and all payment effects.
abstract contract StreamReleaseAuthorization is IStreamSplitWallet, ReentrancyGuard {
    bytes32 public constant RELEASE_AUTHORIZATION_TYPEHASH = keccak256(
        "StreamReleaseAuthorization(address asset,address account,address recipient,uint256 releasableSnapshot,bytes32 nonce,uint64 deadline)"
    );
    bytes32 public constant RELEASE_AUTHORIZATION_REVOCATION_TYPEHASH = keccak256(
        "StreamReleaseAuthorizationRevocation(address account,bytes32 nonce,uint64 deadline)"
    );
    bytes32 private constant _DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    uint256 private constant _HALF_ORDER =
        0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;
    bytes4 private constant _MAGIC = 0x1626ba7e;
    mapping(address => mapping(bytes32 => bool)) private _releaseNonces;

    function domainSeparator() public view override returns (bytes32) {
        return keccak256(
            abi.encode(
                _DOMAIN_TYPEHASH,
                keccak256("6529StreamSplitWallet"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
    }

    function eip712Domain()
        external
        view
        override
        returns (
            bytes1 fields,
            string memory name,
            string memory version,
            uint256 chainId,
            address verifyingContract,
            bytes32 salt,
            uint256[] memory extensions
        )
    {
        return (
            0x0f,
            "6529StreamSplitWallet",
            "1",
            block.chainid,
            address(this),
            bytes32(0),
            new uint256[](0)
        );
    }

    function releaseAuthorizationDigest(ReleaseAuthorization calldata authorization)
        public
        view
        override
        returns (bytes32)
    {
        return _typedReleaseDigest(
            keccak256(abi.encode(RELEASE_AUTHORIZATION_TYPEHASH, authorization))
        );
    }

    function releaseRevocationDigest(address account, bytes32 nonce, uint64 deadline)
        public
        view
        override
        returns (bytes32)
    {
        return _typedReleaseDigest(
            keccak256(
                abi.encode(RELEASE_AUTHORIZATION_REVOCATION_TYPEHASH, account, nonce, deadline)
            )
        );
    }

    function isReleaseAuthorizationNonceUsed(address account, bytes32 nonce)
        public
        view
        override
        returns (bool)
    {
        return _releaseNonces[account][nonce];
    }

    function revokeReleaseAuthorization(bytes32 nonce) external override nonReentrant {
        _revokeRelease(msg.sender, nonce);
    }

    function revokeReleaseAuthorizationBySignature(
        address account,
        bytes32 nonce,
        uint64 deadline,
        bytes calldata signature
    ) external override nonReentrant {
        _requireReleaseUnused(account, nonce);
        if (block.timestamp > deadline) revert ReleaseAuthorizationExpired(deadline);
        if (!_validReleaseSignature(
                account, releaseRevocationDigest(account, nonce, deadline), signature
            )) {
            revert InvalidReleaseSignature(account);
        }
        _revokeRelease(account, nonce);
    }

    function _consumeReleaseAuthorization(
        ReleaseAuthorization calldata authorization,
        bytes calldata signature,
        uint256 actualAmount
    ) internal {
        _requireReleaseUnused(authorization.account, authorization.nonce);
        if (block.timestamp > authorization.deadline) {
            revert ReleaseAuthorizationExpired(authorization.deadline);
        }
        if (authorization.releasableSnapshot != actualAmount) {
            revert ReleaseSnapshotMismatch(authorization.releasableSnapshot, actualAmount);
        }
        if (!_validReleaseSignature(
                authorization.account, releaseAuthorizationDigest(authorization), signature
            )) {
            revert InvalidReleaseSignature(authorization.account);
        }
        _releaseNonces[authorization.account][authorization.nonce] = true;
    }

    function _revokeRelease(address account, bytes32 nonce) private {
        _requireReleaseUnused(account, nonce);
        _releaseNonces[account][nonce] = true;
        emit ReleaseAuthorizationRevoked(account, nonce, 1);
    }

    function _requireReleaseUnused(address account, bytes32 nonce) private view {
        if (account == address(0)) revert InvalidReleaseAccount();
        if (_releaseNonces[account][nonce]) revert ReleaseAuthorizationNonceUsed(account, nonce);
    }

    function _typedReleaseDigest(bytes32 hash) private view returns (bytes32) {
        return keccak256(abi.encodePacked(hex"1901", domainSeparator(), hash));
    }

    function _releaseSignatureGasLimit() internal view virtual returns (uint256);

    function _requireWalletCallGas(uint256 limit) internal view {
        uint256 available = gasleft();
        // The subtraction avoids overflow for even a malformed or unreachable very large limit.
        if (
            limit > available || available - limit < limit / 63 + (limit % 63 == 0 ? 0 : 1) + 20_000
        ) {
            revert InsufficientWalletCallGas(limit);
        }
    }

    function _validReleaseSignature(address account, bytes32 digest, bytes calldata signature)
        private
        view
        returns (bool)
    {
        uint256 size = account.code.length;
        bool delegated;
        if (size == 23) {
            uint256 prefix;
            assembly ("memory-safe") {
                let ptr := mload(0x40)
                extcodecopy(account, ptr, 0, 3)
                prefix := shr(232, mload(ptr))
            }
            delegated = prefix == 0xef0100;
        }
        if (size == 0 || delegated) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            if (signature.length == 65) {
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    s := calldataload(add(signature.offset, 32))
                    v := byte(0, calldataload(add(signature.offset, 64)))
                }
            } else if (signature.length == 64) {
                bytes32 vs;
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    vs := calldataload(add(signature.offset, 32))
                }
                s = vs & bytes32(type(uint256).max >> 1);
                v = uint8(uint256(vs) >> 255) + 27;
            }
            if (
                uint256(s) <= _HALF_ORDER && (v == 27 || v == 28)
                    && ecrecover(digest, v, r, s) == account
            ) return true;
            if (size == 0) return false;
        }
        // Contract signatures have no EOA length constraint (e.g. Safe threshold signatures).
        bytes memory payload = abi.encodeWithSelector(_MAGIC, digest, signature);
        uint256 limit = _releaseSignatureGasLimit();
        _requireWalletCallGas(limit);
        bool success;
        uint256 result;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            success := staticcall(limit, account, add(payload, 32), mload(payload), ptr, 32)
            success := and(success, eq(returndatasize(), 32))
            result := mload(ptr)
        }
        return success && result == uint256(uint32(_MAGIC)) << 224;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/IStreamRevenueEscrow.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/standards/IERC20.sol";
import "../parameters/StreamGasParameterHost.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import { StreamRevenueRuntimeBinding as RuntimeBinding } from "./StreamRevenueRuntimeBinding.sol";
import {
    StreamEscrowRecoveryGovernance as RecoveryGovernance
} from "./StreamEscrowRecoveryGovernance.sol";
import {
    StreamEscrowRecoveryManifest as RecoveryManifest
} from "./StreamEscrowRecoveryManifest.sol";
import { StreamEscrowRecoveryConsent as RecoveryConsent } from "./StreamEscrowRecoveryConsent.sol";
import {
    StreamEscrowRecoveryExecution as RecoveryExecution
} from "./StreamEscrowRecoveryExecution.sol";
import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import "../../interfaces/stream/revenue/IStreamRevenueEscrowRecovery.sol";
import "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";
import { StreamEscrowRecoveryState as RecoveryState } from "./StreamEscrowRecoveryState.sol";
import "../../interfaces/stream/revenue/IStreamRevenueRuntimeBinding.sol";

/// @notice Captured owed revenue with explicit governed runtime admission and incident recovery.
/// @dev Recovery operates only on this escrow ledger; resident old-wallet funds remain untouched.
///      Producer authorization does not independently prove the sale assignment kind.
contract StreamRevenueEscrow is
    IStreamRevenueEscrow,
    StreamGasParameterHost,
    ReentrancyGuard,
    IStreamRevenueRuntimeBinding,
    IStreamRevenueEscrowRecovery,
    IStreamRevenueEscrowRecoveryManifest
{
    uint16 public constant SCHEMA_VERSION = 1;
    bytes32 public constant ESCROW_RECOVERY_DOMAIN = R.RECOVERY_DOMAIN;
    bytes32 public constant ESCROW_RECOVERY_CONSENT_TYPEHASH = R.CONSENT_TYPEHASH;
    bytes32 private constant _FLUSH_GAS = keccak256("6529STREAM_GGP_FLUSH_GAS_FLOOR");
    bytes32 private constant _DEPOSIT_GAS = keccak256("6529STREAM_GGP_WALLET_DEPOSIT_GAS_LIMIT");
    bytes32 private constant _POLICY_GAS = keccak256("6529STREAM_GGP_ASSET_POLICY_GAS_LIMIT");
    bytes32 private constant _PRODUCER_SCOPE = keccak256("6529STREAM_ESCROW_PRODUCER_SCOPE_V1");
    bytes32 private constant _PRODUCER_STATE = keccak256("6529STREAM_ESCROW_PRODUCER_STATE_V1");
    uint256 private constant _CALL_RESERVE = 30_000;

    IStreamSplitFactory public immutable splitFactory;
    IStreamAssetPolicyRegistry public immutable assetPolicyRegistry;
    bytes32 public immutable factoryCodeHash;
    bytes32 public immutable walletCodeHash;
    bytes32 public immutable registryCodeHash;

    struct Producer {
        bool enabled;
        bytes32 codeHash;
        uint64 revision;
        bytes32 lastActionId;
    }

    struct Credit {
        uint256 amount;
        address factory;
        bytes32 factoryHash;
        bytes32 runtimeHash;
    }

    struct Key {
        bytes32 revenueClass;
        bytes32 profileId;
        address wallet;
        address asset;
    }

    struct Action {
        uint256 executing;
        bytes32 id;
        uint256 actionClass;
        bytes32 scope;
        bytes32 oldState;
        bytes32 newState;
    }

    mapping(address => Producer) private _producers;
    mapping(bytes32 => Credit) private _credits;
    mapping(address => uint256) public override totalOwed;

    constructor(
        IStreamSplitFactory factory_,
        address authority,
        GasParameterConfig memory flushConfig
    ) StreamGasParameterHost(authority) {
        if (
            authority == address(0) || address(factory_).code.length == 0
                || _isDelegatedCode(address(factory_))
                || factory_.governanceAuthority() != authority
        ) revert InvalidEscrowConfiguration();
        IStreamAssetPolicyRegistry registry = factory_.assetPolicyRegistry();
        if (
            address(registry).code.length == 0 || _isDelegatedCode(address(registry))
                || registry.governanceAuthority() != authority
                || !registry.isStreamAssetPolicyRegistry()
        ) revert InvalidEscrowConfiguration();
        bytes32 runtime = factory_.splitWalletRuntimeCodeHash();
        if (
            runtime == bytes32(0) || factory_.splitWalletInitCodeHash() == bytes32(0)
                || factory_.gasParameter(_DEPOSIT_GAS) == 0
                || factory_.gasParameter(_POLICY_GAS) == 0
        ) {
            revert InvalidEscrowConfiguration();
        }
        if (
            keccak256(bytes(flushConfig.name)) != keccak256("FLUSH_GAS_FLOOR")
                || flushConfig.failureClass != FAILURE_CLASS_MIN_GAS_GATE
        ) {
            revert GasParameterInvalidConfig(_FLUSH_GAS);
        }
        _registerGasParameter(flushConfig);
        splitFactory = factory_;
        assetPolicyRegistry = registry;
        factoryCodeHash = address(factory_).codehash;
        walletCodeHash = runtime;
        registryCodeHash = address(registry).codehash;
        // Recovery gas inventory is fixed at construction. Old nonadvertising factory
        // fixtures retain their original constructor behavior and cannot opt into recovery.
        if (RuntimeBinding.advertises(address(factory_))) {
            _registerRecoveryGas(factory_, "ERC_1271_GAS_LIMIT");
            _registerRecoveryGas(factory_, "WALLET_DEPOSIT_GAS_LIMIT");
            _registerRecoveryGas(factory_, "ASSET_POLICY_GAS_LIMIT");
        }
    }

    /// @notice Additive opt-in; original captured-credit storage and constructor stay unchanged.
    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7
            || interfaceId == type(IStreamRevenueRuntimeBinding).interfaceId
            || interfaceId == type(IStreamRevenueEscrow).interfaceId
            || interfaceId == type(IStreamRevenueEscrowRecovery).interfaceId
            || interfaceId == type(IStreamRevenueEscrowRecoveryManifest).interfaceId;
    }

    function revenueRuntimeRegistry() external view override returns (address registry) {
        (registry,) = RuntimeBinding.current();
    }

    function revenueRuntimeRegistryCodeHash() external view override returns (bytes32 codeHash) {
        (, codeHash) = RuntimeBinding.current();
    }

    function revenueRuntimeBindingTransitionHashes(address registry)
        external
        view
        override
        returns (bytes32, bytes32, bytes32)
    {
        return RuntimeBinding.transition(
            RuntimeBinding.Context(
                address(splitFactory),
                governanceAuthority,
                address(assetPolicyRegistry),
                _recoveryInitializationHash()
            ),
            registry
        );
    }

    function initializeRevenueRuntimeRegistry(address registry) external override nonReentrant {
        _requireFactory();
        RuntimeBinding.initialize(
            RuntimeBinding.Context(
                address(splitFactory),
                governanceAuthority,
                address(assetPolicyRegistry),
                _recoveryInitializationHash()
            ),
            registry
        );
        RecoveryState.state().origin = RecoveryState.Origin(
            governanceAuthority.codehash,
            splitFactory.PROFILE_DOMAIN(),
            splitFactory.splitWalletInitCodeHash(),
            splitFactory.SCHEMA_VERSION(),
            splitFactory.WALLET_VERSION()
        );
    }

    function _recoveryInitializationHash() private view returns (bytes32) {
        _requireFactory();
        bytes32 signatureGas = keccak256("6529STREAM_GGP_ERC_1271_GAS_LIMIT");
        return keccak256(
            abi.encode(
                governanceAuthority.codehash,
                splitFactory.PROFILE_DOMAIN(),
                splitFactory.splitWalletInitCodeHash(),
                splitFactory.SCHEMA_VERSION(),
                splitFactory.WALLET_VERSION(),
                signatureGas,
                gasParameter(signatureGas),
                _gasParameters[signatureGas].floor,
                _DEPOSIT_GAS,
                gasParameter(_DEPOSIT_GAS),
                _gasParameters[_DEPOSIT_GAS].floor,
                _POLICY_GAS,
                gasParameter(_POLICY_GAS),
                _gasParameters[_POLICY_GAS].floor
            )
        );
    }

    function _registerRecoveryGas(IStreamSplitFactory factory_, string memory name) private {
        bytes32 key = keccak256(abi.encodePacked("6529STREAM_GGP_", name));
        _registerGasParameter(
            GasParameterConfig(
                name,
                factory_.gasParameter(key),
                factory_.gasParameterFloor(key),
                FAILURE_CLASS_FAIL_CLOSED_PRECHECK
            )
        );
    }

    function _recoveryContext() private view returns (RecoveryState.Context memory c) {
        (address registry, bytes32 codeHash) = RuntimeBinding.current();
        if (registry == address(0) || registry.codehash != codeHash) {
            revert InvalidRevenueRuntimeBinding();
        }
        RecoveryState.Origin storage origin = RecoveryState.state().origin;
        if (governanceAuthority.codehash != origin.authorityCodeHash) {
            revert InvalidRevenueRuntimeBinding();
        }
        c = RecoveryState.Context(
            address(splitFactory),
            governanceAuthority,
            address(assetPolicyRegistry),
            factoryCodeHash,
            walletCodeHash,
            origin.initCodeHash,
            origin.profileDomain,
            origin.schemaVersion,
            origin.walletVersion,
            registry,
            codeHash
        );
    }

    function publishEscrowRecoveryManifest(
        ManifestDocument calldata document,
        R.EscrowRecoveryManifestRef calldata manifest
    ) external override nonReentrant returns (bytes32 contentHash) {
        return RecoveryManifest.publish(_recoveryContext(), document, manifest);
    }

    function escrowRecoveryManifest(bytes32 contentHash)
        external
        view
        override
        returns (bytes memory canonicalDocument, uint64 publishedAt)
    {
        return RecoveryManifest.encoded(contentHash);
    }

    function escrowRecoveryAffectedAccountCount(bytes32 contentHash)
        external
        view
        override
        returns (uint256)
    {
        return RecoveryManifest.count(contentHash);
    }

    function escrowRecoveryAffectedAccountAt(bytes32 contentHash, uint256 index)
        external
        view
        override
        returns (address)
    {
        return RecoveryManifest.accountAt(contentHash, index);
    }

    function scheduleEscrowRecovery(
        R.EscrowCreditKey calldata creditKey,
        address successorWallet,
        bytes32 successorProfileId,
        bytes32 successorRuntimeCodeHash,
        uint256 expectedAmount,
        R.EscrowRecoveryManifestRef calldata recoveryManifest,
        uint64 executeAfter,
        bytes32 reasonHash,
        string calldata reasonURI
    ) external override nonReentrant returns (bytes32 recoveryId) {
        return RecoveryGovernance.schedule(
            _recoveryContext(),
            R.EscrowRecoveryRecord(
                R.EscrowRecoveryStatus.SCHEDULED,
                creditKey,
                address(splitFactory),
                successorWallet,
                successorProfileId,
                successorRuntimeCodeHash,
                expectedAmount,
                recoveryManifest,
                executeAfter,
                reasonHash,
                reasonURI
            )
        );
    }

    function escrowRecoveryTransitionHashes(
        R.EscrowCreditKey calldata creditKey,
        address successorWallet,
        bytes32 successorProfileId,
        bytes32 successorRuntimeCodeHash,
        uint256 expectedAmount,
        R.EscrowRecoveryManifestRef calldata recoveryManifest,
        uint64 executeAfter,
        bytes32 reasonHash,
        string calldata reasonURI
    )
        external
        view
        override
        returns (bytes32 recoveryId, bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        return RecoveryGovernance.transition(
            _recoveryContext(),
            R.EscrowRecoveryRecord(
                R.EscrowRecoveryStatus.SCHEDULED,
                creditKey,
                address(splitFactory),
                successorWallet,
                successorProfileId,
                successorRuntimeCodeHash,
                expectedAmount,
                recoveryManifest,
                executeAfter,
                reasonHash,
                reasonURI
            )
        );
    }

    function cancelEscrowRecovery(bytes32 recoveryId, bytes32 reasonHash, string calldata reasonURI)
        external
        override
        nonReentrant
    {
        // Cancellation remains possible independently of live successor or registry admission.
        RecoveryGovernance.cancel(governanceAuthority, recoveryId, reasonHash, reasonURI);
    }

    function escrowRecoveryCancellationHashes(
        bytes32 recoveryId,
        bytes32 reasonHash,
        string calldata reasonURI
    )
        external
        view
        override
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        return RecoveryGovernance.cancellation(recoveryId, reasonHash, reasonURI);
    }

    function authorizeTerminalEscrowRecovery(bytes32 recoveryId) external override nonReentrant {
        RecoveryGovernance.terminal(_recoveryContext(), recoveryId);
    }

    function escrowRecoveryTerminalHashes(bytes32 recoveryId)
        external
        view
        override
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        return RecoveryGovernance.terminalHashes(recoveryId);
    }

    function executeEscrowRecovery(bytes32 recoveryId) external override nonReentrant {
        RecoveryExecution.execute(_credits, totalOwed, _recoveryContext(), recoveryId);
    }

    function escrowRecoveryRecord(bytes32 recoveryId)
        external
        view
        override
        returns (R.EscrowRecoveryRecord memory)
    {
        return RecoveryState.state().recoveries[recoveryId].record;
    }

    function submitEscrowRecoveryConsent(
        address account,
        bytes32 recoveryId,
        bytes32 nonce,
        uint64 deadline,
        bytes calldata signature
    ) external override nonReentrant {
        RecoveryConsent.submit(account, recoveryId, nonce, deadline, signature);
    }

    function recordEscrowRecoveryConsent(bytes32 recoveryId, bytes32 nonce)
        external
        override
        nonReentrant
    {
        RecoveryConsent.record(recoveryId, nonce);
    }

    function revokeEscrowRecoveryConsent(bytes32 recoveryId) external override nonReentrant {
        RecoveryConsent.revoke(recoveryId);
    }

    function escrowRecoveryConsentRecorded(bytes32 recoveryId, address account)
        external
        view
        override
        returns (bool)
    {
        return RecoveryConsent.recorded(recoveryId, account);
    }

    function isEscrowRecoveryConsentNonceUsed(address account, bytes32 nonce)
        external
        view
        override
        returns (bool)
    {
        return RecoveryConsent.nonceUsed(account, nonce);
    }

    function escrowRecoveryDomainSeparator() external view returns (bytes32) {
        return RecoveryConsent.domainSeparator();
    }

    function escrowRecoveryConsentDigest(
        address account,
        bytes32 recoveryId,
        bytes32 nonce,
        uint64 deadline
    ) external view returns (bytes32) {
        return RecoveryConsent.digest(account, recoveryId, nonce, deadline);
    }

    function _requireRuntime(bool active) private view {
        (address registry, bytes32 codeHash) = RuntimeBinding.current();
        if (registry == address(0)) {
            (registry, codeHash) = RuntimeBinding.factoryBinding(address(splitFactory));
        }
        if (registry != address(0)) {
            RuntimeBinding.requireState(address(splitFactory), registry, codeHash, active);
        }
    }

    /// @notice Passive native receipts are surplus; only creditNative records owed funds.
    receive() external payable { }

    function gasParameterFloor(bytes32 parameterId) external view override returns (uint256) {
        gasParameter(parameterId);
        return _gasParameters[parameterId].floor;
    }

    function creditProducer(address producer)
        external
        view
        override
        returns (bool enabled, bytes32 codeHash, uint64 revision)
    {
        Producer storage item = _producers[producer];
        return (item.enabled, item.codeHash, item.revision);
    }

    function creditProducerTransitionHashes(address producer, bool enabled)
        public
        view
        override
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        Producer storage item = _producers[producer];
        bytes32 nextHash = enabled ? _admissibleProducerCode(producer) : item.codeHash;
        if (
            item.revision == type(uint64).max
                || (item.enabled == enabled && item.codeHash == nextHash)
        ) {
            revert InvalidEscrowProducer(producer);
        }
        scopeHash = keccak256(abi.encode(_PRODUCER_SCOPE, block.chainid, address(this), producer));
        oldStateHash = keccak256(
            abi.encode(_PRODUCER_STATE, scopeHash, item.enabled, item.codeHash, item.revision)
        );
        newStateHash =
            keccak256(abi.encode(_PRODUCER_STATE, scopeHash, enabled, nextHash, item.revision + 1));
    }

    function setCreditProducer(address producer, bool enabled) external override nonReentrant {
        if (msg.sender != governanceAuthority) revert InvalidEscrowProducerAction();
        (bytes32 scope, bytes32 oldState, bytes32 newState) =
            creditProducerTransitionHashes(producer, enabled);
        Action memory action = _action();
        Producer storage item = _producers[producer];
        if (
            action.executing != 1 || action.id == bytes32(0) || action.actionClass != 1
                || action.scope != scope || action.oldState != oldState
                || action.newState != newState || item.lastActionId == action.id
        ) revert InvalidEscrowProducerAction();
        if (enabled) item.codeHash = _admissibleProducerCode(producer);
        item.enabled = enabled;
        ++item.revision;
        item.lastActionId = action.id;
        emit EscrowProducerUpdated(
            SCHEMA_VERSION, producer, item.codeHash, action.id, enabled, item.revision
        );
    }

    function creditNative(
        bytes32 revenueClass,
        bytes32 profileId,
        address wallet,
        bool templateOrigin
    ) external payable override nonReentrant {
        _requireProducer();
        Key memory key = Key(revenueClass, profileId, wallet, address(0));
        _requireCredit(key, msg.value, templateOrigin);
        _requireSolvent(address(0), address(this).balance - msg.value);
        _recordCredit(key, msg.value);
    }

    function creditERC20(
        bytes32 revenueClass,
        bytes32 profileId,
        address wallet,
        address asset,
        uint256 amount,
        bool templateOrigin
    ) external override nonReentrant {
        _requireProducer();
        if (asset == address(0) || asset.code.length == 0) revert InvalidEscrowCredit();
        Key memory key = Key(revenueClass, profileId, wallet, asset);
        _requireCredit(key, amount, templateOrigin);
        _requireActive(asset);
        uint256 cap = _factoryGas(_DEPOSIT_GAS);
        _moveToken(asset, msg.sender, address(this), amount, cap, true);
        // A token callback cannot bypass the current policy check or the shared guard.
        _requireActive(asset);
        _requireRuntime(true);
        _recordCredit(key, amount);
    }

    function escrowOwed(bytes32 revenueClass, bytes32 profileId, address wallet, address asset)
        external
        view
        override
        returns (uint256)
    {
        return _credits[_keyHash(Key(revenueClass, profileId, wallet, asset))].amount;
    }

    function escrowCreditIdentity(
        bytes32 revenueClass,
        bytes32 profileId,
        address wallet,
        address asset
    ) external view override returns (address factory, bytes32 factoryHash, bytes32 runtimeHash) {
        Credit storage item = _credits[_keyHash(Key(revenueClass, profileId, wallet, asset))];
        return (item.factory, item.factoryHash, item.runtimeHash);
    }

    function surplus(address asset) external view override returns (uint256) {
        uint256 balance = asset == address(0)
            ? address(this).balance
            : _tokenBalance(asset, address(this), _factoryGas(_DEPOSIT_GAS));
        return balance > totalOwed[asset] ? balance - totalOwed[asset] : 0;
    }

    function flushEscrow(bytes32 revenueClass, bytes32 profileId, address wallet, address asset)
        external
        override
        nonReentrant
    {
        uint256 required = gasParameter(_FLUSH_GAS);
        if (gasleft() < required) revert InsufficientEscrowGas(required, gasleft());
        _flush(Key(revenueClass, profileId, wallet, asset), true);
    }

    function flushToVerifiedWalletBestEffort(
        bytes32 revenueClass,
        bytes32 profileId,
        address wallet,
        address asset
    ) external override nonReentrant {
        // Deliberately independent of the possibly unaffordable undeployed-wallet floor.
        _flush(Key(revenueClass, profileId, wallet, asset), false);
    }

    function _flush(Key memory key, bool mayDeploy) private {
        _requireFactory();
        _requireRuntime(false);
        Credit storage credit = _credits[_keyHash(key)];
        uint256 amount = credit.amount;
        if (amount == 0) revert NoEscrowCredit();
        if (
            credit.factory != address(splitFactory) || credit.factoryHash != factoryCodeHash
                || credit.runtimeHash != walletCodeHash
        ) revert InvalidEscrowConfiguration();
        uint256 cap = _factoryGas(_DEPOSIT_GAS);
        uint256 balance = key.asset == address(0)
            ? address(this).balance
            : _tokenBalance(key.asset, address(this), cap);
        _requireSolvent(key.asset, balance);
        credit.amount = 0;
        totalOwed[key.asset] -= amount;
        if (key.wallet.code.length == 0) {
            if (!mayDeploy) revert EscrowFixedWalletUndeployed(key.profileId, key.wallet);
            // Reserve several deposit/read calls and accounting work while forwarding the
            // remaining budget to trusted deployment code. This is not a fixed deployment cap.
            uint256 available = gasleft();
            if (available <= 100_000 || cap > (available - 100_000) / 6) {
                revert InsufficientEscrowCallGas(cap, available, 100_000);
            }
            uint256 reserve = cap * 6 + 100_000;
            bytes memory data = abi.encodeCall(IStreamSplitFactory.deployWallet, (key.profileId));
            uint256 deployGas = gasleft() - reserve;
            deployGas -= deployGas / 64;
            uint256 result = _callWord(address(splitFactory), data, 0, deployGas);
            if (result != uint256(uint160(key.wallet))) {
                revert EscrowWalletMismatch(key.profileId, key.wallet);
            }
        }
        _verifyWallet(key.profileId, key.wallet, false);
        if (key.asset == address(0)) {
            uint256 walletBefore = key.wallet.balance;
            _nativeDeposit(key.wallet, amount, cap);
            if (
                key.wallet.balance != walletBefore + amount
                    || address(this).balance != balance - amount
            ) {
                revert EscrowTransferInvariantBroken(address(0));
            }
        } else {
            // Retained credits do not reapply ACTIVE admission: deprecation cannot erase owed funds.
            _moveToken(key.asset, address(this), key.wallet, amount, cap, false);
        }
        _requireRuntime(false);
        emit EscrowFlushed(
            key.revenueClass, key.profileId, key.wallet, SCHEMA_VERSION, key.asset, amount, 0
        );
    }

    function _requireCredit(Key memory key, uint256 amount, bool templateOrigin) private view {
        if (key.revenueClass == bytes32(0) || amount == 0 || key.wallet == address(0)) {
            revert InvalidEscrowCredit();
        }
        _requireFactory();
        _requireRuntime(true);
        _verifyWallet(key.profileId, key.wallet, templateOrigin);
    }

    function _verifyWallet(bytes32 profileId, address wallet, bool mayBeUndeployed) private view {
        if (!splitFactory.profileExists(profileId)) revert EscrowUnknownProfile(profileId);
        if (wallet != splitFactory.walletFor(profileId)) {
            revert EscrowWalletMismatch(profileId, wallet);
        }
        if (wallet.code.length == 0) {
            if (!mayBeUndeployed) revert EscrowFixedWalletUndeployed(profileId, wallet);
        } else {
            if (wallet.codehash != walletCodeHash) {
                revert WrongCodeAtWallet(wallet, walletCodeHash, wallet.codehash);
            }
            if (
                !splitFactory.splitWalletExists(profileId)
                    || IStreamSplitWallet(wallet).factory() != address(splitFactory)
                    || IStreamSplitWallet(wallet).profileId() != profileId
            ) {
                revert EscrowWalletMismatch(profileId, wallet);
            }
        }
    }

    function _recordCredit(Key memory key, uint256 amount) private {
        Credit storage item = _credits[_keyHash(key)];
        if (item.factory == address(0)) {
            item.factory = address(splitFactory);
            item.factoryHash = factoryCodeHash;
            item.runtimeHash = walletCodeHash;
        }
        item.amount += amount;
        totalOwed[key.asset] += amount;
        emit EscrowCreditCreated(
            key.revenueClass,
            key.profileId,
            key.wallet,
            SCHEMA_VERSION,
            key.asset,
            amount,
            item.amount,
            walletCodeHash
        );
    }

    function _requireSolvent(address asset, uint256 balance) private view {
        if (balance < totalOwed[asset]) revert EscrowInsolvent(asset, balance, totalOwed[asset]);
    }

    function _requireFactory() private view {
        if (address(splitFactory).codehash != factoryCodeHash) {
            revert EscrowFactoryCodeChanged(address(splitFactory));
        }
    }

    function _requireProducer() private view {
        Producer storage item = _producers[msg.sender];
        if (!item.enabled || _admissibleProducerCode(msg.sender) != item.codeHash) {
            revert InvalidEscrowProducer(msg.sender);
        }
    }

    function _admissibleProducerCode(address producer) private view returns (bytes32) {
        if (producer.code.length == 0 || _isDelegatedCode(producer)) {
            revert InvalidEscrowProducer(producer);
        }
        return producer.codehash;
    }

    function _isDelegatedCode(address target) private view returns (bool) {
        if (target.code.length == 23) {
            uint256 prefix;
            assembly ("memory-safe") {
                let ptr := mload(0x40)
                extcodecopy(target, ptr, 0, 3)
                prefix := shr(232, mload(ptr))
            }
            return prefix == 0xef0100;
        }
        return false;
    }

    function _keyHash(Key memory key) private pure returns (bytes32) {
        return keccak256(abi.encode(key.revenueClass, key.profileId, key.wallet, key.asset));
    }

    function _requireActive(address asset) private view {
        address registry = address(assetPolicyRegistry);
        if (registry.codehash != registryCodeHash) {
            revert EscrowReadFailed(registry, IStreamAssetPolicyRegistry.assetStatus.selector);
        }
        uint256 status = _readWord(
            registry,
            abi.encodeCall(IStreamAssetPolicyRegistry.assetStatus, (asset)),
            _factoryGas(_POLICY_GAS)
        );
        if (status != 1) revert EscrowAssetNotActive(asset, status);
    }

    function _factoryGas(bytes32 parameterId) private view returns (uint256 value) {
        _requireFactory();
        address target = address(splitFactory);
        bytes memory data = abi.encodeCall(IStreamGasParameterHost.gasParameter, (parameterId));
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(gas(), target, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            value := mload(ptr)
        }
        if (!ok || value == 0) {
            revert EscrowReadFailed(target, IStreamGasParameterHost.gasParameter.selector);
        }
    }

    function _requireCallGas(uint256 cap) private view {
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + _CALL_RESERVE)
        {
            revert InsufficientEscrowCallGas(cap, available, _CALL_RESERVE);
        }
    }

    function _readWord(address target, bytes memory data, uint256 cap)
        private
        view
        returns (uint256 value)
    {
        _requireCallGas(cap);
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(cap, target, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            value := mload(ptr)
        }
        // Casting to bytes4 extracts the selector from internally ABI-encoded calldata.
        // forge-lint: disable-next-line(unsafe-typecast)
        if (!ok) revert EscrowReadFailed(target, bytes4(data));
    }

    function _callWord(address target, bytes memory data, uint256 value, uint256 cap)
        private
        returns (uint256 word)
    {
        _requireCallGas(cap);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := call(cap, target, value, add(data, 32), mload(data), ptr, 32)
            size := returndatasize()
            word := mload(ptr)
        }
        // Casting to bytes4 extracts the selector from internally ABI-encoded calldata.
        // forge-lint: disable-next-line(unsafe-typecast)
        if (!ok || size != 32) _failedCall(target, bytes4(data), size);
    }

    function _nativeDeposit(address wallet, uint256 amount, uint256 cap) private {
        _requireCallGas(cap);
        // CALL adds the value-transfer stipend. Keep the total callee budget at the GGP value.
        if (cap < 2300) revert InsufficientEscrowCallGas(cap, gasleft(), 2300);
        uint256 forwarded = cap - 2300;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(forwarded, wallet, amount, 0, 0, 0, 0)
            size := returndatasize()
        }
        if (!ok) _failedCall(wallet, bytes4(0), size);
    }

    function _failedCall(address target, bytes4 selector, uint256 size) private pure {
        uint256 length = size > 256 ? 256 : size;
        bytes memory prefix = new bytes(length);
        assembly ("memory-safe") { returndatacopy(add(prefix, 32), 0, length) }
        revert EscrowExternalCallFailed(target, selector, size, prefix);
    }

    function _tokenBalance(address asset, address account, uint256 cap)
        private
        view
        returns (uint256)
    {
        return _readWord(asset, abi.encodeCall(IERC20.balanceOf, (account)), cap);
    }

    function _moveToken(
        address asset,
        address from,
        address to,
        uint256 amount,
        uint256 cap,
        bool pull
    ) private {
        uint256 fromBefore = _tokenBalance(asset, from, cap);
        uint256 toBefore = _tokenBalance(asset, to, cap);
        if (pull) _requireSolvent(asset, toBefore);
        if (fromBefore < amount) revert EscrowTransferInvariantBroken(asset);
        bytes memory data = pull
            ? abi.encodeCall(IERC20.transferFrom, (from, to, amount))
            : abi.encodeCall(IERC20.transfer, (to, amount));
        if (_callWord(asset, data, 0, cap) != 1) revert EscrowTransferInvariantBroken(asset);
        if (
            _tokenBalance(asset, from, cap) != fromBefore - amount
                || _tokenBalance(asset, to, cap) != toBefore + amount
        ) {
            revert EscrowTransferInvariantBroken(asset);
        }
    }

    function _action() private view returns (Action memory action) {
        address authority = governanceAuthority;
        uint256 selector = uint32(IStreamGovernedParameterAuthority.currentAction.selector);
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, shl(224, selector))
            ok := staticcall(gas(), authority, ptr, 4, action, 192)
            ok := and(ok, eq(returndatasize(), 192))
        }
        if (!ok) revert InvalidEscrowProducerAction();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/IStreamRevenueRuntimeRegistry.sol";
import "../../interfaces/stream/revenue/IStreamRevenueRuntimeBinding.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";

/// @notice Fixed binding/admission worker; each host retains its own once-only pointer.
/// @dev Old unbound factories preserve their initial admission. Deployment activation must
///      separately require opt-in; a selected/advertised malformed registry never falls back.
library StreamRevenueRuntimeBinding {
    bytes32 private constant SLOT = keccak256("6529STREAM_REVENUE_RUNTIME_BINDING_STORAGE_V1");
    bytes32 private constant DOMAIN = keccak256("6529STREAM_REVENUE_RUNTIME_BINDING_V1");
    bytes32 private constant READ_GAS = keccak256("6529STREAM_GGP_REVENUE_RUNTIME_READ_GAS");
    bytes4 private constant ERC165 = 0x01ffc9a7;

    struct State {
        address registry;
        bytes32 codeHash;
    }

    struct Context {
        address factory;
        address authority;
        address assetRegistry;
        bytes32 initializationHash;
    }

    struct Action {
        uint256 executing;
        bytes32 id;
        uint256 actionClass;
        bytes32 scope;
        bytes32 oldState;
        bytes32 newState;
    }

    event RevenueRuntimeRegistryBound(
        uint16 schemaVersion,
        address indexed registry,
        bytes32 indexed actionId,
        bytes32 registryCodeHash,
        address indexed factory
    );

    function state() internal pure returns (State storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function current() public view returns (address registry, bytes32 codeHash) {
        State storage s = state();
        return (s.registry, s.codeHash);
    }

    function transition(Context memory c, address registry)
        public
        view
        returns (bytes32 scope, bytes32 oldValue, bytes32 newValue)
    {
        if (state().registry != address(0)) {
            revert IStreamRevenueRuntimeBinding.RevenueRuntimeAlreadyBound();
        }
        _candidate(c, registry);
        scope = keccak256(abi.encode(DOMAIN, block.chainid, address(this), c));
        oldValue = keccak256(abi.encode(scope, address(0), bytes32(0)));
        newValue = keccak256(abi.encode(scope, registry, registry.codehash));
    }

    function initialize(Context memory c, address registry) public {
        if (msg.sender != c.authority) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        (bytes32 scope, bytes32 oldValue, bytes32 newValue) = transition(c, registry);
        bytes memory output = _read(
            c.authority,
            abi.encodeCall(IStreamGovernedParameterAuthority.currentAction, ()),
            192,
            _budget(registry)
        );
        Action memory a = abi.decode(output, (Action));
        if (
            a.executing != 1 || a.id == 0 || a.actionClass != 1 || a.scope != scope
                || a.oldState != oldValue || a.newState != newValue
        ) revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        State storage s = state();
        s.registry = registry;
        s.codeHash = registry.codehash;
        emit RevenueRuntimeRegistryBound(1, registry, a.id, s.codeHash, c.factory);
    }

    /// @notice Mutation admission only; stored policy hashes/disclosures do not call this.
    function requireActive(address factory) public view {
        (address registry, bytes32 codeHash) = factoryBinding(factory);
        if (registry == address(0)) return;
        requireState(factory, registry, codeHash, true);
    }

    function requireState(address factory, address registry, bytes32 codeHash, bool active)
        public
        view
    {
        if (registry.codehash != codeHash || codeHash == 0) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        uint256 cap = _budget(registry);
        IStreamRevenueRuntimeRegistry.FactoryRecord memory f = abi.decode(
            _read(
                registry,
                abi.encodeCall(IStreamRevenueRuntimeRegistry.factoryRecord, (factory)),
                192,
                cap
            ),
            (IStreamRevenueRuntimeRegistry.FactoryRecord)
        );
        IStreamRevenueRuntimeRegistry.RuntimeRecord memory r = abi.decode(
            _read(
                registry,
                abi.encodeCall(IStreamRevenueRuntimeRegistry.runtimeRecord, (f.runtimeCodeHash)),
                128,
                cap
            ),
            (IStreamRevenueRuntimeRegistry.RuntimeRecord)
        );
        if (
            f.codeHash != factory.codehash || f.codeHash == 0 || f.revision == 0 || r.revision == 0
                || f.runtimeCodeHash == 0
                || (active
                        ? f.status != 1 || r.status != 1
                        : (f.status != 1 && f.status != 2) || (r.status != 1 && r.status != 2))
        ) {
            revert IStreamRevenueRuntimeRegistry.RevenueRuntimeUnavailable(
                factory, f.runtimeCodeHash, r.status
            );
        }
    }

    /// @notice Optional old-factory capability probe; successful malformed replies fail closed.
    function advertises(address factory) public view returns (bool) {
        bytes memory query =
            abi.encodeWithSelector(ERC165, type(IStreamRevenueRuntimeBinding).interfaceId);
        uint256 advertised;
        uint256 size;
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(30000, factory, add(query, 32), mload(query), ptr, 32)
            size := returndatasize()
            advertised := mload(ptr)
        }
        // Original factories without this selector may revert or return no bytes.
        if (!ok || size == 0) return false;
        if (size != 32 || advertised > 1) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        return advertised == 1;
    }

    function factoryBinding(address factory)
        public
        view
        returns (address registry, bytes32 codeHash)
    {
        if (!advertises(factory)) return (address(0), 0);
        uint256 raw = _word(
            factory, abi.encodeCall(IStreamRevenueRuntimeBinding.revenueRuntimeRegistry, ()), 30000
        );
        if (raw > type(uint160).max) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        registry = address(uint160(raw));
        codeHash = bytes32(
            _word(
                factory,
                abi.encodeCall(IStreamRevenueRuntimeBinding.revenueRuntimeRegistryCodeHash, ()),
                30000
            )
        );
        if ((registry == address(0)) != (codeHash == 0)) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        if (registry != address(0) && registry.codehash != codeHash) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
    }

    function _candidate(Context memory c, address registry) private view {
        if (
            registry.code.length == 0 || c.factory.code.length == 0 || _delegated(registry)
                || _delegated(c.factory) || _delegated(c.authority)
        ) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        uint256 cap = _budget(registry);
        if (
            _word(
                        registry,
                        abi.encodeCall(
                            IStreamRevenueRuntimeRegistry.isStreamRevenueRuntimeRegistry, ()
                        ),
                        cap
                    ) != 1
                || _word(
                        registry,
                        abi.encodeCall(IStreamGasParameterHost.governanceAuthority, ()),
                        cap
                    ) != uint256(uint160(c.authority))
                || bytes32(
                        _word(
                            registry,
                            abi.encodeCall(IStreamRevenueRuntimeRegistry.authorityCodeHash, ()),
                            cap
                        )
                    ) != c.authority.codehash
                || _word(
                        registry,
                        abi.encodeCall(IStreamRevenueRuntimeRegistry.assetPolicyRegistry, ()),
                        cap
                    ) != uint256(uint160(c.assetRegistry))
        ) revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        requireState(c.factory, registry, registry.codehash, true);
        if (address(this) != c.factory) {
            (address selected, bytes32 codeHash) = factoryBinding(c.factory);
            if (selected != registry || codeHash != registry.codehash) {
                revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
            }
        }
    }

    function _delegated(address target) private view returns (bool) {
        if (target.code.length != 23) return false;
        uint256 prefix;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            extcodecopy(target, ptr, 0, 3)
            prefix := shr(232, mload(ptr))
        }
        return prefix == 0xef0100;
    }

    function _budget(address registry) private view returns (uint256 cap) {
        cap = _word(
            registry, abi.encodeCall(IStreamGasParameterHost.gasParameter, (READ_GAS)), 30000
        );
        if (cap == 0) revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
    }

    function _word(address target, bytes memory data, uint256 cap) private view returns (uint256) {
        return abi.decode(_read(target, data, 32, cap), (uint256));
    }

    function _read(address target, bytes memory data, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory output)
    {
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + 1 + 15000) {
            revert IStreamRevenueRuntimeBinding.InvalidRevenueRuntimeBinding();
        }
        output = new bytes(length);
        bool ok;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), add(output, 32), length)
            ok := and(ok, eq(returndatasize(), length))
        }
        if (!ok) {
            revert IStreamRevenueRuntimeRegistry.RevenueRuntimeReadFailed(target, bytes4(data));
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/IStreamRevenueRuntimeRegistry.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../parameters/StreamGasParameterHost.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";

/// @notice Governed common factory/runtime lifecycle; it never holds or transfers revenue.
/// @dev ACTIVE=1, DEPRECATED=2, INCIDENT_REVOKED=3. A first approved factory also
///      explicitly approves its previously unknown runtime in the same committed action.
contract StreamRevenueRuntimeRegistry is
    IStreamRevenueRuntimeRegistry,
    StreamGasParameterHost,
    ReentrancyGuard
{
    bytes32 private constant READ_GAS = keccak256("6529STREAM_GGP_REVENUE_RUNTIME_READ_GAS");
    bytes32 private constant FACTORY_SCOPE = keccak256("6529STREAM_REVENUE_FACTORY_LIFECYCLE_V1");
    bytes32 private constant RUNTIME_SCOPE = keccak256("6529STREAM_REVENUE_RUNTIME_LIFECYCLE_V1");
    address public immutable override assetPolicyRegistry;
    bytes32 public immutable override authorityCodeHash;
    bytes32 public immutable assetPolicyCodeHash;
    mapping(address => FactoryRecord) private _factories;
    mapping(bytes32 => RuntimeRecord) private _runtimes;

    struct Action {
        uint256 executing;
        bytes32 id;
        uint256 actionClass;
        bytes32 scope;
        bytes32 oldState;
        bytes32 newState;
    }

    constructor(address authority, address assetRegistry, GasParameterConfig memory readConfig)
        StreamGasParameterHost(authority)
    {
        if (
            authority.code.length == 0 || assetRegistry.code.length == 0 || _delegated(authority)
                || _delegated(assetRegistry)
                || IStreamAssetPolicyRegistry(assetRegistry).governanceAuthority() != authority
                || !IStreamAssetPolicyRegistry(assetRegistry).isStreamAssetPolicyRegistry()
                || keccak256(bytes(readConfig.name)) != keccak256("REVENUE_RUNTIME_READ_GAS")
                || readConfig.failureClass != FAILURE_CLASS_FAIL_CLOSED_PRECHECK
        ) revert InvalidRevenueRuntimeConfiguration();
        assetPolicyRegistry = assetRegistry;
        authorityCodeHash = authority.codehash;
        assetPolicyCodeHash = assetRegistry.codehash;
        _registerGasParameter(readConfig);
    }

    function gasParameterFloor(bytes32 parameterId) external view returns (uint256) {
        gasParameter(parameterId);
        return _gasParameters[parameterId].floor;
    }

    function isStreamRevenueRuntimeRegistry() external pure override returns (bool) {
        return true;
    }

    function factoryRecord(address factory) external view override returns (FactoryRecord memory) {
        return _factories[factory];
    }

    function runtimeRecord(bytes32 codeHash) external view override returns (RuntimeRecord memory) {
        return _runtimes[codeHash];
    }

    function factoryTransitionHashes(
        address factory,
        uint8 status,
        bytes32 reasonHash,
        string calldata reasonURI,
        bytes32 incidentManifestHash
    )
        public
        view
        override
        returns (uint8 actionClass, bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        _reason(status, reasonHash, reasonURI, incidentManifestHash);
        FactoryRecord memory prior = _factories[factory];
        (bytes32 codeHash, bytes32 runtime) = _nextFactory(factory, status, prior);
        RuntimeRecord memory runtimeState = _runtimes[runtime];
        actionClass = prior.revision == 0 || status < prior.status ? 1 : 0;
        scopeHash = keccak256(abi.encode(FACTORY_SCOPE, block.chainid, address(this), factory));
        oldStateHash = keccak256(abi.encode(scopeHash, prior, runtimeState));
        newStateHash = keccak256(
            abi.encode(
                scopeHash,
                codeHash,
                runtime,
                status,
                prior.revision + 1,
                runtimeState,
                reasonHash,
                keccak256(bytes(reasonURI)),
                incidentManifestHash
            )
        );
    }

    function runtimeTransitionHashes(
        bytes32 runtime,
        uint8 status,
        bytes32 reasonHash,
        string calldata reasonURI,
        bytes32 incidentManifestHash
    )
        public
        view
        override
        returns (uint8 actionClass, bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash)
    {
        _reason(status, reasonHash, reasonURI, incidentManifestHash);
        RuntimeRecord memory prior = _runtimes[runtime];
        if (prior.revision == 0 || prior.revision == type(uint64).max || status == prior.status) {
            revert InvalidRevenueRuntimeTransition();
        }
        actionClass = prior.revision == 0 || status < prior.status ? 1 : 0;
        scopeHash = keccak256(abi.encode(RUNTIME_SCOPE, block.chainid, address(this), runtime));
        oldStateHash = keccak256(abi.encode(scopeHash, prior));
        newStateHash = keccak256(
            abi.encode(
                scopeHash,
                status,
                prior.revision + 1,
                reasonHash,
                keccak256(bytes(reasonURI)),
                incidentManifestHash
            )
        );
    }

    function setFactoryStatus(
        address factory,
        uint8 status,
        bytes32 reasonHash,
        string calldata reasonURI,
        bytes32 incidentManifestHash
    ) external override nonReentrant {
        (uint8 cls, bytes32 scope, bytes32 oldState, bytes32 newState) =
            factoryTransitionHashes(factory, status, reasonHash, reasonURI, incidentManifestHash);
        FactoryRecord storage item = _factories[factory];
        Action memory action = _requireAction(cls, scope, oldState, newState, item.lastActionId);
        (bytes32 codeHash, bytes32 runtime) = _nextFactory(factory, status, item);
        RuntimeRecord storage runtimeState = _runtimes[runtime];
        if (runtimeState.revision == 0) {
            runtimeState.status = 1;
            runtimeState.revision = 1;
            runtimeState.lastActionId = action.id;
            emit RevenueRuntimeStatusChanged(1, runtime, action.id, 1, 1, reasonHash, reasonURI, 0);
        }
        item.status = status;
        item.codeHash = codeHash;
        item.runtimeCodeHash = runtime;
        item.incidentManifestHash = incidentManifestHash;
        ++item.revision;
        item.lastActionId = action.id;
        emit RevenueFactoryStatusChanged(
            1,
            factory,
            runtime,
            action.id,
            codeHash,
            status,
            item.revision,
            reasonHash,
            reasonURI,
            incidentManifestHash
        );
    }

    function setRuntimeStatus(
        bytes32 runtime,
        uint8 status,
        bytes32 reasonHash,
        string calldata reasonURI,
        bytes32 incidentManifestHash
    ) external override nonReentrant {
        (uint8 cls, bytes32 scope, bytes32 oldState, bytes32 newState) =
            runtimeTransitionHashes(runtime, status, reasonHash, reasonURI, incidentManifestHash);
        RuntimeRecord storage item = _runtimes[runtime];
        Action memory action = _requireAction(cls, scope, oldState, newState, item.lastActionId);
        item.status = status;
        ++item.revision;
        item.incidentManifestHash = incidentManifestHash;
        item.lastActionId = action.id;
        emit RevenueRuntimeStatusChanged(
            1,
            runtime,
            action.id,
            status,
            item.revision,
            reasonHash,
            reasonURI,
            incidentManifestHash
        );
    }

    function _nextFactory(address factory, uint8 status, FactoryRecord memory prior)
        private
        view
        returns (bytes32 codeHash, bytes32 runtime)
    {
        if (
            factory == address(0) || prior.revision == type(uint64).max || prior.status == status
                || (prior.revision == 0 && status != 1)
        ) revert InvalidRevenueRuntimeTransition();
        if (status != 1) return (prior.codeHash, prior.runtimeCodeHash);
        codeHash = factory.codehash;
        if (
            factory.code.length == 0 || _delegated(factory)
                || (prior.revision != 0 && prior.codeHash != codeHash)
                || assetPolicyRegistry.codehash != assetPolicyCodeHash
        ) revert InvalidRevenueRuntimeConfiguration();
        if (
            _word(factory, abi.encodeCall(IStreamGasParameterHost.governanceAuthority, ()))
                    != uint256(uint160(governanceAuthority))
                || _word(factory, abi.encodeCall(IStreamSplitFactory.assetPolicyRegistry, ()))
                    != uint256(uint160(assetPolicyRegistry))
        ) revert InvalidRevenueRuntimeConfiguration();
        runtime = bytes32(
            _word(factory, abi.encodeCall(IStreamSplitFactory.splitWalletRuntimeCodeHash, ()))
        );
        if (
            runtime == 0
                || _word(factory, abi.encodeCall(IStreamSplitFactory.splitWalletInitCodeHash, ()))
                    == 0 || (prior.revision != 0 && prior.runtimeCodeHash != runtime)
                || (_runtimes[runtime].revision != 0 && _runtimes[runtime].status != 1)
        ) revert InvalidRevenueRuntimeConfiguration();
    }

    function _reason(uint8 status, bytes32 reasonHash, string calldata uri, bytes32 manifest)
        private
        pure
    {
        if (
            status < 1 || status > 3 || reasonHash == 0 || bytes(uri).length == 0
                || bytes(uri).length > 2048 || (status == 3 && manifest == 0)
        ) revert InvalidRevenueRuntimeTransition();
    }

    function _requireAction(
        uint8 cls,
        bytes32 scope,
        bytes32 oldState,
        bytes32 newState,
        bytes32 last
    ) private view returns (Action memory action) {
        if (msg.sender != governanceAuthority || governanceAuthority.codehash != authorityCodeHash)
        {
            revert InvalidRevenueRuntimeAction();
        }
        address target = governanceAuthority;
        bytes memory data = abi.encodeCall(IStreamGovernedParameterAuthority.currentAction, ());
        bool ok;
        uint256 cap = gasParameter(READ_GAS);
        _gas(cap);
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), action, 192)
            ok := and(ok, eq(returndatasize(), 192))
        }
        if (
            !ok || action.executing != 1 || action.id == 0 || action.id == last
                || action.actionClass != cls || action.scope != scope || action.oldState != oldState
                || action.newState != newState
        ) revert InvalidRevenueRuntimeAction();
    }

    function _word(address target, bytes memory data) private view returns (uint256 result) {
        uint256 cap = gasParameter(READ_GAS);
        _gas(cap);
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(cap, target, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            result := mload(ptr)
        }
        if (!ok) revert RevenueRuntimeReadFailed(target, bytes4(data));
    }

    function _delegated(address target) private view returns (bool) {
        if (target.code.length != 23) return false;
        uint256 prefix;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            extcodecopy(target, ptr, 0, 3)
            prefix := shr(232, mload(ptr))
        }
        return prefix == 0xef0100;
    }

    function _gas(uint256 cap) private view {
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + 1 + 15_000) {
            revert InvalidRevenueRuntimeConfiguration();
        }
    }
}

