// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/stream/revenue/IStreamSplitWalletImplementation.sol";
import "./StreamSplitWalletDeployment.sol";
import { StreamRevenueRuntimeBinding as RuntimeBinding } from "./StreamRevenueRuntimeBinding.sol";
import "../../interfaces/stream/revenue/IStreamRevenueRuntimeBinding.sol";
import "../parameters/StreamGasParameterHost.sol";

/// @notice Registers immutable split profiles and deploys their deterministic split wallets.
contract StreamSplitFactory is
    IStreamSplitFactory,
    StreamGasParameterHost,
    IStreamRevenueRuntimeBinding,
    IStreamSplitWalletImplementation
{
    uint8 private constant _ASSET_STATUS_ACTIVE = 1;

    /// @notice Domain separator label for v1 split profile identifiers.
    bytes32 public constant override PROFILE_DOMAIN = keccak256("6529STREAM_SPLIT_PROFILE_V1");
    /// @notice Split profile schema version used in profile identifiers and events.
    uint16 public constant override SCHEMA_VERSION = 1;
    /// @notice Split wallet implementation version used in profile identifiers and events.
    uint16 public constant override WALLET_VERSION = 4;
    /// @notice Maximum canonical split entries accepted by one profile.
    uint16 public constant override MAX_ENTRIES = 64;
    /// @notice Maximum unique recipient accounts accepted by one profile.
    uint16 public constant override MAX_UNIQUE_ACCOUNTS = 64;
    /// @notice Parts-per-million denominator for split shares.
    uint32 public constant override SHARE_DENOMINATOR_PPM = 1_000_000;
    /// @notice Deployment-wide registry for approved standard ERC-20 split assets.
    IStreamAssetPolicyRegistry public immutable override assetPolicyRegistry;
    /// @notice Actual singleton implementation for genesis role 6; never a user wallet.
    address public immutable override splitWalletImplementation;
    bytes32 public immutable override splitWalletImplementationCodeHash;
    bytes32 private immutable _splitWalletInitCodeHash;
    bytes32 private immutable _splitWalletRuntimeCodeHash;

    struct Profile {
        bool exists;
        bytes32 entriesHash;
        bytes32 metadataURIHash;
        address wallet;
        IStreamSplitWallet.SplitEntry[] entries;
        address[] accounts;
        uint32[] aggregateSharePpm;
    }

    mapping(bytes32 => Profile) private _profiles;
    bytes32[] private _profileIds;

    constructor(
        IStreamAssetPolicyRegistry assetPolicyRegistry_,
        address authority,
        GasParameterConfig[3] memory walletGasConfigs
    ) StreamGasParameterHost(authority) {
        if (authority == address(0)) {
            revert GasParameterInvalidAuthority(authority);
        }
        for (uint256 i; i < 3; ++i) {
            bytes32 expected = i == 0
                ? keccak256("ERC_1271_GAS_LIMIT")
                : i == 1
                    ? keccak256("ASSET_POLICY_GAS_LIMIT")
                    : keccak256("WALLET_DEPOSIT_GAS_LIMIT");
            if (
                keccak256(bytes(walletGasConfigs[i].name)) != expected
                    || walletGasConfigs[i].failureClass != FAILURE_CLASS_FAIL_CLOSED_PRECHECK
            ) {
                revert GasParameterInvalidConfig(expected);
            }
            _registerGasParameter(walletGasConfigs[i]);
        }
        if (address(assetPolicyRegistry_).code.length == 0) {
            revert InvalidAssetPolicyRegistry(address(assetPolicyRegistry_));
        }
        try assetPolicyRegistry_.isStreamAssetPolicyRegistry() returns (bool ok) {
            if (!ok) {
                revert InvalidAssetPolicyRegistry(address(assetPolicyRegistry_));
            }
        } catch {
            revert InvalidAssetPolicyRegistry(address(assetPolicyRegistry_));
        }
        try assetPolicyRegistry_.ASSET_STATUS_ACTIVE() returns (uint8 activeStatus) {
            if (activeStatus != _ASSET_STATUS_ACTIVE) {
                revert InvalidAssetPolicyRegistry(address(assetPolicyRegistry_));
            }
        } catch {
            revert InvalidAssetPolicyRegistry(address(assetPolicyRegistry_));
        }

        assetPolicyRegistry = assetPolicyRegistry_;
        emit AssetPolicyRegistryPinned(address(assetPolicyRegistry_));
        address implementation = StreamSplitWalletDeployment.deployImplementation();
        splitWalletImplementation = implementation;
        splitWalletImplementationCodeHash = implementation.codehash;
        _splitWalletInitCodeHash = StreamSplitWalletDeployment.initCodeHash(implementation);
        _splitWalletRuntimeCodeHash = StreamSplitWalletDeployment.runtimeCodeHash(implementation);
        emit SplitWalletImplementationPinned(
            SCHEMA_VERSION,
            implementation,
            implementation.codehash,
            WALLET_VERSION,
            _splitWalletInitCodeHash,
            _splitWalletRuntimeCodeHash
        );
    }

    /// @notice Exact additive lifecycle capability; old factory interface entries remain unchanged.
    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7
            || interfaceId == type(IStreamRevenueRuntimeBinding).interfaceId
            || interfaceId == type(IStreamSplitWalletImplementation).interfaceId
            || interfaceId == type(IStreamSplitFactory).interfaceId;
    }

    function revenueRuntimeRegistry() external view override returns (address registry) {
        (registry,) = RuntimeBinding.current();
    }

    function revenueRuntimeRegistryCodeHash() external view override returns (bytes32 codeHash) {
        (, codeHash) = RuntimeBinding.current();
    }

    function revenueRuntimeBindingTransitionHashes(address registry)
        external
        view
        override
        returns (bytes32, bytes32, bytes32)
    {
        return RuntimeBinding.transition(
            RuntimeBinding.Context(
                address(this), governanceAuthority, address(assetPolicyRegistry), bytes32(0)
            ),
            registry
        );
    }

    function initializeRevenueRuntimeRegistry(address registry) external override {
        RuntimeBinding.initialize(
            RuntimeBinding.Context(
                address(this), governanceAuthority, address(assetPolicyRegistry), bytes32(0)
            ),
            registry
        );
    }

    /// @notice Immutable constructor floor for a registered wallet-line gas budget.
    function gasParameterFloor(bytes32 parameterId) external view override returns (uint256) {
        gasParameter(parameterId);
        return _gasParameters[parameterId].floor;
    }

    /// @notice Returns the creation-code hash used for deterministic wallet addresses.
    function splitWalletInitCodeHash() public view override returns (bytes32) {
        return _splitWalletInitCodeHash;
    }

    /// @notice Returns the runtime-code hash accepted for deployed split wallets.
    function splitWalletRuntimeCodeHash() public view override returns (bytes32) {
        return _splitWalletRuntimeCodeHash;
    }

    /// @notice Creates or reuses a canonical split profile and deploys its deterministic wallet.
    function createProfile(
        IStreamSplitWallet.SplitEntry[] calldata entries,
        bytes32 metadataURIHash
    ) external override returns (bytes32 profileId, address wallet) {
        profileId = _registerProfile(entries, metadataURIHash);
        wallet = _deployWallet(profileId);
    }

    /// @notice Registers or reuses a canonical profile without deploying or funding its wallet.
    /// @dev The predicted address is not a verified wallet until deployWallet succeeds.
    function registerProfile(
        IStreamSplitWallet.SplitEntry[] calldata entries,
        bytes32 metadataURIHash
    ) external override returns (bytes32 profileId, address wallet) {
        profileId = _registerProfile(entries, metadataURIHash);
        wallet = walletFor(profileId);
    }

    function _registerProfile(
        IStreamSplitWallet.SplitEntry[] calldata entries,
        bytes32 metadataURIHash
    ) private returns (bytes32 profileId) {
        RuntimeBinding.requireActive(address(this));
        (
            IStreamSplitWallet.SplitEntry[] memory canonicalEntries,
            address[] memory accounts,
            uint32[] memory aggregateShares,
            bytes32 entriesHash
        ) = _canonicalize(entries);
        profileId = _profileId(entriesHash, metadataURIHash);

        Profile storage profile = _profiles[profileId];
        bool created = !profile.exists;
        if (created) {
            profile.exists = true;
            profile.entriesHash = entriesHash;
            profile.metadataURIHash = metadataURIHash;
            _profileIds.push(profileId);
            for (uint256 i = 0; i < canonicalEntries.length; i++) {
                profile.entries.push(canonicalEntries[i]);
            }
            for (uint256 i = 0; i < accounts.length; i++) {
                profile.accounts.push(accounts[i]);
                profile.aggregateSharePpm.push(aggregateShares[i]);
            }
            emit SplitProfileCreated(
                profileId,
                entriesHash,
                metadataURIHash,
                SCHEMA_VERSION,
                WALLET_VERSION,
                walletFor(profileId)
            );
            for (uint256 i = 0; i < canonicalEntries.length; i++) {
                IStreamSplitWallet.SplitEntry memory splitEntry = canonicalEntries[i];
                emit SplitProfileEntry(
                    profileId,
                    // Safe because MAX_ENTRIES is 64, well below the uint16 limit.
                    // forge-lint: disable-next-line(unsafe-typecast)
                    uint16(i),
                    splitEntry.account,
                    SCHEMA_VERSION,
                    splitEntry.sharePpm,
                    splitEntry.labelId
                );
            }
        }
    }

    /// @notice Number of canonical profiles registered, including undeployed wallets.
    function profileCount() external view override returns (uint256) {
        return _profileIds.length;
    }

    /// @notice Immutable creation-order profile ID; an out-of-range index reverts.
    function profileAt(uint256 index) external view override returns (bytes32 profileId) {
        return _profileIds[index];
    }

    /// @notice Predicted wallet for a creation-order profile, deployed or not.
    function walletAt(uint256 index) external view override returns (address wallet) {
        return walletFor(_profileIds[index]);
    }

    /// @notice Deploys the deterministic wallet for an existing profile if it is not deployed.
    function deployWallet(bytes32 profileId) external override returns (address wallet) {
        if (!_profiles[profileId].exists) {
            revert UnknownProfile(profileId);
        }
        wallet = _deployWallet(profileId);
    }

    /// @notice Returns whether a split profile has been created by this factory.
    function profileExists(bytes32 profileId) external view override returns (bool) {
        return _profiles[profileId].exists;
    }

    /// @notice Returns true when the profile wallet is deployed with expected code and metadata.
    function splitWalletExists(bytes32 profileId) external view override returns (bool) {
        Profile storage profile = _profiles[profileId];
        if (!profile.exists) {
            return false;
        }
        return _walletMatchesProfile(profileId, walletFor(profileId), profile);
    }

    /// @notice Returns the immutable metadata URI hash committed by a split profile.
    function profileMetadataURIHash(bytes32 profileId) external view override returns (bytes32) {
        return _profiles[profileId].metadataURIHash;
    }

    /// @notice Returns the canonical entry hash committed by a split profile.
    function profileEntriesHash(bytes32 profileId) external view override returns (bytes32) {
        return _profiles[profileId].entriesHash;
    }

    /// @notice Returns the CREATE2 wallet address for a profile whether or not it is deployed.
    function walletFor(bytes32 profileId) public view override returns (address) {
        return address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(
                            bytes1(0xff), address(this), profileId, splitWalletInitCodeHash()
                        )
                    )
                )
            )
        );
    }

    /// @notice Computes the profile identifier for entries after canonical sorting.
    function profileIdFor(IStreamSplitWallet.SplitEntry[] calldata entries, bytes32 metadataURIHash)
        external
        view
        override
        returns (bytes32)
    {
        (,,, bytes32 entriesHash) = _canonicalize(entries);
        return _profileId(entriesHash, metadataURIHash);
    }

    /// @notice Returns the number of canonical entries stored for a profile.
    function profileEntryCount(bytes32 profileId) external view override returns (uint256) {
        return _profiles[profileId].entries.length;
    }

    /// @notice Returns one canonical profile entry by sorted index.
    function profileEntry(bytes32 profileId, uint256 index)
        external
        view
        override
        returns (address account, uint32 sharePpm, bytes32 labelId)
    {
        IStreamSplitWallet.SplitEntry storage splitEntry = _profiles[profileId].entries[index];
        return (splitEntry.account, splitEntry.sharePpm, splitEntry.labelId);
    }

    /// @notice Returns the number of unique accounts after label-level shares are aggregated.
    function profileUniqueAccountCount(bytes32 profileId) external view override returns (uint256) {
        return _profiles[profileId].accounts.length;
    }

    /// @notice Returns one unique account and its aggregate share by sorted account index.
    function profileUniqueAccount(bytes32 profileId, uint256 index)
        external
        view
        override
        returns (address account, uint32 sharePpm)
    {
        Profile storage profile = _profiles[profileId];
        account = profile.accounts[index];
        sharePpm = profile.aggregateSharePpm[index];
    }

    function _deployWallet(bytes32 profileId) private returns (address wallet) {
        if (splitWalletImplementation.codehash != splitWalletImplementationCodeHash) {
            revert SplitWalletImplementationChanged(
                splitWalletImplementation,
                splitWalletImplementationCodeHash,
                splitWalletImplementation.codehash
            );
        }
        Profile storage profile = _profiles[profileId];
        wallet = walletFor(profileId);
        if (wallet.code.length != 0) {
            if (wallet.codehash != splitWalletRuntimeCodeHash()) {
                revert SplitWalletAddressPoisoned(profileId, wallet);
            }
            _validateExistingWallet(profileId, wallet, profile);
            if (profile.wallet == address(0)) {
                profile.wallet = wallet;
                emit SplitWalletDiscovered(
                    profileId,
                    wallet,
                    WALLET_VERSION,
                    SCHEMA_VERSION,
                    splitWalletInitCodeHash(),
                    splitWalletRuntimeCodeHash()
                );
            }
            return wallet;
        }

        wallet = StreamSplitWalletDeployment.deploy(splitWalletImplementation, profileId);
        IStreamSplitWallet splitWallet = IStreamSplitWallet(wallet);
        splitWallet.initialize(
            profileId,
            profile.entriesHash,
            profile.metadataURIHash,
            _copyEntries(profile),
            _copyAccounts(profile),
            _copyAggregateShares(profile)
        );
        profile.wallet = wallet;
        emit SplitWalletDeployed(
            profileId,
            wallet,
            WALLET_VERSION,
            SCHEMA_VERSION,
            splitWalletInitCodeHash(),
            splitWalletRuntimeCodeHash()
        );
    }

    function _validateExistingWallet(bytes32 profileId, address wallet, Profile storage profile)
        private
        view
    {
        if (!_walletMatchesProfile(profileId, wallet, profile)) {
            revert SplitWalletAddressPoisoned(profileId, wallet);
        }
    }

    function _walletMatchesProfile(bytes32 profileId, address wallet, Profile storage profile)
        private
        view
        returns (bool)
    {
        if (
            splitWalletImplementation.codehash != splitWalletImplementationCodeHash
                || wallet.code.length == 0 || wallet.codehash != splitWalletRuntimeCodeHash()
        ) {
            return false;
        }
        IStreamSplitWallet splitWallet = IStreamSplitWallet(wallet);
        try splitWallet.factory() returns (address walletFactory) {
            if (walletFactory != address(this)) {
                return false;
            }
        } catch {
            return false;
        }
        try splitWallet.initialized() returns (bool walletInitialized) {
            if (!walletInitialized) {
                return false;
            }
        } catch {
            return false;
        }
        try splitWallet.profileId() returns (bytes32 walletProfileId) {
            if (walletProfileId != profileId) {
                return false;
            }
        } catch {
            return false;
        }
        try splitWallet.entriesHash() returns (bytes32 walletEntriesHash) {
            if (walletEntriesHash != profile.entriesHash) {
                return false;
            }
        } catch {
            return false;
        }
        try splitWallet.metadataURIHash() returns (bytes32 walletMetadataURIHash) {
            return walletMetadataURIHash == profile.metadataURIHash;
        } catch {
            return false;
        }
    }

    function _profileId(bytes32 entriesHash, bytes32 metadataURIHash)
        private
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                PROFILE_DOMAIN,
                uint256(block.chainid),
                address(this),
                SCHEMA_VERSION,
                WALLET_VERSION,
                splitWalletInitCodeHash(),
                splitWalletRuntimeCodeHash(),
                address(assetPolicyRegistry),
                entriesHash,
                metadataURIHash
            )
        );
    }

    function _canonicalize(IStreamSplitWallet.SplitEntry[] calldata entries)
        private
        pure
        returns (
            IStreamSplitWallet.SplitEntry[] memory canonicalEntries,
            address[] memory accounts,
            uint32[] memory aggregateShares,
            bytes32 entriesHash
        )
    {
        uint256 length = entries.length;
        if (length == 0 || length > MAX_ENTRIES) {
            revert InvalidEntryCount(length);
        }

        canonicalEntries = new IStreamSplitWallet.SplitEntry[](length);
        for (uint256 i = 0; i < length; i++) {
            canonicalEntries[i] = entries[i];
        }
        _sortEntries(canonicalEntries);

        address[] memory accountBuffer = new address[](length);
        uint32[] memory shareBuffer = new uint32[](length);
        uint256 uniqueCount = 0;
        uint256 totalShare = 0;
        for (uint256 i = 0; i < length; i++) {
            IStreamSplitWallet.SplitEntry memory splitEntry = canonicalEntries[i];
            if (splitEntry.account == address(0)) {
                revert InvalidSplitAccount(i);
            }
            if (splitEntry.sharePpm == 0) {
                revert InvalidSplitShare(i);
            }
            if (splitEntry.sharePpm > SHARE_DENOMINATOR_PPM) {
                revert InvalidSplitShare(i);
            }
            if (
                i != 0 && canonicalEntries[i - 1].account == splitEntry.account
                    && canonicalEntries[i - 1].labelId == splitEntry.labelId
            ) {
                revert DuplicateSplitEntry(splitEntry.account, splitEntry.labelId);
            }

            totalShare += splitEntry.sharePpm;
            if (i == 0 || canonicalEntries[i - 1].account != splitEntry.account) {
                uniqueCount++;
                if (uniqueCount > MAX_UNIQUE_ACCOUNTS) {
                    revert InvalidEntryCount(length);
                }
                accountBuffer[uniqueCount - 1] = splitEntry.account;
            }
            shareBuffer[uniqueCount - 1] += splitEntry.sharePpm;
        }
        if (totalShare != SHARE_DENOMINATOR_PPM) {
            revert InvalidSplitTotal(totalShare);
        }

        accounts = new address[](uniqueCount);
        aggregateShares = new uint32[](uniqueCount);
        for (uint256 i = 0; i < uniqueCount; i++) {
            accounts[i] = accountBuffer[i];
            aggregateShares[i] = shareBuffer[i];
        }
        entriesHash = keccak256(abi.encode(canonicalEntries));
    }

    function _sortEntries(IStreamSplitWallet.SplitEntry[] memory entries) private pure {
        for (uint256 i = 1; i < entries.length; i++) {
            IStreamSplitWallet.SplitEntry memory current = entries[i];
            uint256 j = i;
            while (j > 0 && _entryLess(current, entries[j - 1])) {
                entries[j] = entries[j - 1];
                j--;
            }
            entries[j] = current;
        }
    }

    function _entryLess(
        IStreamSplitWallet.SplitEntry memory left,
        IStreamSplitWallet.SplitEntry memory right
    ) private pure returns (bool) {
        if (left.account != right.account) {
            return uint160(left.account) < uint160(right.account);
        }
        if (left.labelId != right.labelId) {
            return uint256(left.labelId) < uint256(right.labelId);
        }
        return left.sharePpm < right.sharePpm;
    }

    function _copyEntries(Profile storage profile)
        private
        view
        returns (IStreamSplitWallet.SplitEntry[] memory entries)
    {
        entries = new IStreamSplitWallet.SplitEntry[](profile.entries.length);
        for (uint256 i = 0; i < profile.entries.length; i++) {
            entries[i] = profile.entries[i];
        }
    }

    function _copyAccounts(Profile storage profile)
        private
        view
        returns (address[] memory accounts)
    {
        accounts = new address[](profile.accounts.length);
        for (uint256 i = 0; i < profile.accounts.length; i++) {
            accounts[i] = profile.accounts[i];
        }
    }

    function _copyAggregateShares(Profile storage profile)
        private
        view
        returns (uint32[] memory aggregateShares)
    {
        aggregateShares = new uint32[](profile.aggregateSharePpm.length);
        for (uint256 i = 0; i < profile.aggregateSharePpm.length; i++) {
            aggregateShares[i] = profile.aggregateSharePpm[i];
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/standards/IERC20.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";

import "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import "../../vendor/openzeppelin/Math.sol";
import "./StreamReleaseAuthorization.sol";

/// @notice Pull-payment split wallet for one immutable split profile.
contract StreamSplitWallet is StreamReleaseAuthorization {
    uint8 private constant _ASSET_STATUS_ACTIVE = 1;
    uint8 private constant _ASSET_STATUS_DEPRECATED = 3;
    bytes32 private constant _ASSET_POLICY_GAS_ID =
        keccak256("6529STREAM_GGP_ASSET_POLICY_GAS_LIMIT");
    bytes32 private constant _ERC1271_GAS_ID = keccak256("6529STREAM_GGP_ERC_1271_GAS_LIMIT");

    /// @notice Parts-per-million denominator for split shares.
    uint32 public constant override SHARE_DENOMINATOR_PPM = 1_000_000;
    /// @notice Factory that deployed this wallet and is allowed to initialize it once.
    address public override factory;
    /// @notice Whether the factory has initialized the immutable split profile.
    bool public override initialized;
    /// @notice Profile identifier that binds wallet code, entries, metadata, chain, and factory.
    bytes32 public override profileId;
    /// @notice Canonical hash of the split entries used to initialize this wallet.
    bytes32 public override entriesHash;
    /// @notice Hash of the off-chain profile metadata URI for catalogue and provenance material.
    bytes32 public override metadataURIHash;

    SplitEntry[] private _entries;
    address[] private _uniqueAccounts;
    /// @notice Aggregate parts-per-million share for a unique account across all labels.
    mapping(address => uint32) public override aggregateSharePpm;
    /// @notice Amount released for an account by asset address.
    mapping(address => mapping(address => uint256)) public override accountReleased;
    /// @notice Total amount released by asset address.
    mapping(address => uint256) public override totalReleased;
    /// @notice Whether an asset observation has emitted its initialization event.
    mapping(address => bool) public override assetObservationInitialized;
    /// @notice Last observed cumulative receipts value recorded through syncAsset or release.
    mapping(address => uint256) public override lastObservedReceived;

    // Bound into the singleton implementation runtime, shared by its immutable clones.
    address private immutable _initializingFactory;
    address private immutable _implementation;

    constructor() {
        _initializingFactory = msg.sender;
        _implementation = address(this);
        factory = msg.sender;
        // The implementation is never a user wallet. Clone storage starts at zero.
        initialized = true;
    }

    /// @notice Accepts native ETH receipts passively for later pull release.
    receive() external payable { }

    /// @notice Returns the deployment-wide asset policy registry pinned by the factory.
    function assetPolicyRegistry() public view override returns (address registry) {
        registry = _assetPolicyRegistryOrRevert(address(0));
    }

    /// @notice Initializes the wallet with immutable entries and aggregate account shares.
    function initialize(
        bytes32 profileId_,
        bytes32 entriesHash_,
        bytes32 metadataURIHash_,
        SplitEntry[] calldata entries_,
        address[] calldata accounts_,
        uint32[] calldata aggregateSharePpm_
    ) external override {
        if (msg.sender != _initializingFactory) {
            revert UnauthorizedInitializer(msg.sender);
        }
        if (initialized || address(this) == _implementation) {
            revert AlreadyInitialized();
        }
        IStreamSplitFactory origin = IStreamSplitFactory(_initializingFactory);
        // walletFor is CREATE2-derived, independent of the wallet field published after init.
        if (!origin.profileExists(profileId_) || origin.walletFor(profileId_) != address(this)) {
            revert InvalidInitializationInput();
        }
        if (entries_.length == 0 || accounts_.length == 0) {
            revert InvalidInitializationInput();
        }
        if (accounts_.length != aggregateSharePpm_.length) {
            revert InvalidInitializationInput();
        }
        if (keccak256(abi.encode(entries_)) != entriesHash_) {
            revert InvalidInitializationInput();
        }

        initialized = true;
        factory = _initializingFactory;
        profileId = profileId_;
        entriesHash = entriesHash_;
        metadataURIHash = metadataURIHash_;

        uint256 entryTotal = 0;
        uint256 aggregateTotal = 0;
        for (uint256 i = 0; i < entries_.length; i++) {
            if (entries_[i].account == address(0) || entries_[i].sharePpm == 0) {
                revert InvalidInitializationInput();
            }
            entryTotal += entries_[i].sharePpm;
            _entries.push(entries_[i]);
        }
        for (uint256 i = 0; i < accounts_.length; i++) {
            address account = accounts_[i];
            uint32 sharePpm = aggregateSharePpm_[i];
            if (account == address(0) || sharePpm == 0 || aggregateSharePpm[account] != 0) {
                revert InvalidInitializationInput();
            }
            uint256 expectedSharePpm = 0;
            for (uint256 j = 0; j < entries_.length; j++) {
                if (entries_[j].account == account) {
                    expectedSharePpm += entries_[j].sharePpm;
                }
            }
            if (expectedSharePpm != sharePpm) {
                revert InvalidInitializationInput();
            }
            _uniqueAccounts.push(account);
            aggregateSharePpm[account] = sharePpm;
            aggregateTotal += sharePpm;
        }
        if (entryTotal != SHARE_DENOMINATOR_PPM) {
            revert InvalidInitializationInput();
        }
        if (aggregateTotal != SHARE_DENOMINATOR_PPM) {
            revert InvalidInitializationInput();
        }
    }

    /// @notice Returns the number of canonical label-level split entries.
    function entryCount() external view override returns (uint256) {
        return _entries.length;
    }

    /// @notice Returns one canonical label-level split entry.
    function entry(uint256 index)
        external
        view
        override
        returns (address account, uint32 sharePpm, bytes32 labelId)
    {
        SplitEntry storage splitEntry = _entries[index];
        return (splitEntry.account, splitEntry.sharePpm, splitEntry.labelId);
    }

    /// @notice Returns the number of unique accounts after label shares are aggregated.
    function uniqueAccountCount() external view override returns (uint256) {
        return _uniqueAccounts.length;
    }

    /// @notice Returns one unique account and its aggregate share by sorted account index.
    function uniqueAccount(uint256 index)
        external
        view
        override
        returns (address account, uint32 sharePpm)
    {
        account = _uniqueAccounts[index];
        sharePpm = aggregateSharePpm[account];
    }

    /// @notice Returns cumulative native receipts observed as current balance plus released funds.
    function observedReceived(address asset) public view override returns (uint256) {
        return _currentBalance(asset) + totalReleased[asset];
    }

    /// @notice Returns the currently releasable native amount for an account.
    function releasable(address asset, address account) public view override returns (uint256) {
        uint32 sharePpm = aggregateSharePpm[account];
        if (sharePpm == 0) {
            _requireSupportedAsset(asset);
            return 0;
        }

        uint256 entitlement = Math.mulDiv(observedReceived(asset), sharePpm, SHARE_DENOMINATOR_PPM);
        uint256 released = accountReleased[asset][account];
        if (entitlement <= released) {
            return 0;
        }
        return entitlement - released;
    }

    /// @notice Returns unreleasable native dust caused by integer division rounding.
    function roundingDust(address asset) external view override returns (uint256) {
        uint256 totalReleasable = 0;
        for (uint256 i = 0; i < _uniqueAccounts.length; i++) {
            totalReleasable += releasable(asset, _uniqueAccounts[i]);
        }
        uint256 currentBalance = _currentBalance(asset);
        if (totalReleasable >= currentBalance) {
            return 0;
        }
        return currentBalance - totalReleasable;
    }

    /// @notice Emits the current cumulative receipt observation for the native asset.
    function syncAsset(address asset) external override nonReentrant returns (uint256 observed) {
        observed = observedReceived(asset);
        _recordObservation(asset, observed);
    }

    /// @notice Pulls releasable native funds for an account to that account or its chosen recipient.
    function release(address asset, address account, address payable recipient)
        external
        override
        nonReentrant
        returns (uint256 amount)
    {
        _requireSupportedAsset(asset);
        if (recipient == address(0)) revert ZeroRecipient();
        if (recipient != account && msg.sender != account) {
            revert UnauthorizedReleaseRecipient(msg.sender, account, recipient);
        }
        uint256 observed;
        (observed, amount) = _prepareRelease(asset, account, recipient);
        _executeRelease(asset, account, recipient, observed, amount);
    }

    /// @notice Relays exact full-amount wallet-domain consent, including contract-wallet signatures.
    function releaseWithAuthorization(
        ReleaseAuthorization calldata authorization,
        bytes calldata signature
    ) external override nonReentrant returns (uint256 amount) {
        uint256 observed;
        (observed, amount) =
            _prepareRelease(authorization.asset, authorization.account, authorization.recipient);
        _consumeReleaseAuthorization(authorization, signature, amount);
        _executeRelease(
            authorization.asset,
            authorization.account,
            payable(authorization.recipient),
            observed,
            amount
        );
    }

    function _prepareRelease(address asset, address account, address recipient)
        private
        returns (uint256 observed, uint256 amount)
    {
        if (recipient == address(0)) revert ZeroRecipient();
        observed = observedReceived(asset);
        _recordObservation(asset, observed);
        uint256 entitlement =
            Math.mulDiv(observed, aggregateSharePpm[account], SHARE_DENOMINATOR_PPM);
        uint256 released = accountReleased[asset][account];
        amount = entitlement > released ? entitlement - released : 0;
        if (amount == 0) {
            revert NoReleasableFunds(asset, account);
        }
    }

    function _executeRelease(
        address asset,
        address account,
        address payable recipient,
        uint256 observed,
        uint256 amount
    ) private {
        accountReleased[asset][account] += amount;
        totalReleased[asset] += amount;

        if (asset == address(0)) {
            (bool success,) = recipient.call{ value: amount }("");
            if (!success) {
                revert NativeTransferFailed(recipient, amount);
            }

            uint256 postTransferObserved = observedReceived(asset);
            if (postTransferObserved != observed) {
                revert NativeReceiptInvariantBroken(observed, postTransferObserved);
            }
            _recordObservation(asset, observed);

            emit NativeReleased(
                profileId, account, recipient, amount, totalReleased[asset], observed
            );
            return;
        }

        _transferERC20(asset, recipient, amount);
        uint256 postERC20Observed = observedReceived(asset);
        if (postERC20Observed != observed) {
            revert ObservedReceiptsDecreased(asset, observed, postERC20Observed);
        }
        _recordObservation(asset, observed);

        emit ERC20Released(
            profileId, asset, account, recipient, amount, totalReleased[asset], observed
        );
    }

    function _recordObservation(address asset, uint256 observed) private {
        if (!assetObservationInitialized[asset]) {
            assetObservationInitialized[asset] = true;
            lastObservedReceived[asset] = observed;
            emit AssetObservationInitialized(profileId, asset, observed);
            return;
        }

        uint256 previous = lastObservedReceived[asset];
        if (observed < previous) {
            revert ObservedReceiptsDecreased(asset, previous, observed);
        }
        if (observed == previous) {
            return;
        }
        lastObservedReceived[asset] = observed;
        emit AssetSynced(profileId, asset, previous, observed);
    }

    function _requireSupportedAsset(address asset) private view {
        if (asset == address(0)) {
            return;
        }
        if (asset.code.length == 0) {
            revert UnsupportedAsset(asset);
        }
        address registry = _assetPolicyRegistryOrRevert(asset);
        (bool success, uint256 statusWord) =
            _readAssetPolicyWord(registry, asset, IStreamAssetPolicyRegistry.assetStatus.selector);
        if (!success) {
            revert AssetPolicyReadFailed(registry, asset);
        }
        if (statusWord > type(uint8).max) {
            revert AssetPolicyReadFailed(registry, asset);
        }
        // Safe because statusWord is bounded to uint8 above.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint8 status = uint8(statusWord);
        if (status == _ASSET_STATUS_ACTIVE) return;
        if (status == _ASSET_STATUS_DEPRECATED) {
            if (assetObservationInitialized[asset]) return;
            (success, statusWord) = _readAssetPolicyWord(
                registry, asset, IStreamAssetPolicyRegistry.assetReleaseGraceUntil.selector
            );
            if (!success || statusWord > type(uint64).max) {
                revert AssetPolicyReadFailed(registry, asset);
            }
            if (block.timestamp < statusWord) return;
        }
        revert AssetNotActive(asset, status);
    }

    function _currentBalance(address asset) private view returns (uint256) {
        _requireSupportedAsset(asset);
        if (asset == address(0)) {
            return address(this).balance;
        }
        return _erc20BalanceOf(asset, address(this));
    }

    function _assetPolicyRegistryOrRevert(address asset) private view returns (address registry) {
        (bool success, bytes memory data) = factory.staticcall(
            abi.encodeWithSelector(IStreamSplitFactory.assetPolicyRegistry.selector)
        );
        if (!success || data.length != 32) {
            revert AssetPolicyReadFailed(factory, asset);
        }
        registry = abi.decode(data, (address));
        if (registry.code.length == 0) {
            revert AssetPolicyReadFailed(registry, asset);
        }
    }

    function _readAssetPolicyWord(address registry, address asset, bytes4 operation)
        private
        view
        returns (bool success, uint256 statusWord)
    {
        uint256 selector = uint32(operation);
        uint256 gasLimit = _walletGasParameter(_ASSET_POLICY_GAS_ID);
        _requireWalletCallGas(gasLimit);
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, shl(224, selector))
            mstore(add(ptr, 0x04), asset)
            success := staticcall(gasLimit, registry, ptr, 0x24, 0, 0)
            if iszero(and(success, eq(returndatasize(), 0x20))) { success := 0 }
            if success {
                returndatacopy(ptr, 0, 0x20)
                statusWord := mload(ptr)
            }
        }
    }

    function _releaseSignatureGasLimit() internal view override returns (uint256) {
        return _walletGasParameter(_ERC1271_GAS_ID);
    }

    function _walletGasParameter(bytes32 parameterId) private view returns (uint256 value) {
        address target = factory;
        uint256 selector = uint32(IStreamGasParameterHost.gasParameter.selector);
        bool success;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, shl(224, selector))
            mstore(add(ptr, 4), parameterId)
            success := staticcall(gas(), target, ptr, 36, ptr, 32)
            success := and(success, eq(returndatasize(), 32))
            value := mload(ptr)
        }
        if (!success || value == 0) revert WalletGasParameterReadFailed(parameterId);
    }

    function _erc20BalanceOf(address asset, address account) private view returns (uint256 amount) {
        bool success;
        uint256 selector = uint32(IERC20.balanceOf.selector);
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, shl(224, selector))
            mstore(add(ptr, 0x04), account)
            success := staticcall(gas(), asset, ptr, 0x24, 0, 0)
            if iszero(and(success, eq(returndatasize(), 0x20))) { success := 0 }
            if success {
                returndatacopy(ptr, 0, 0x20)
                amount := mload(ptr)
            }
        }
        if (!success) {
            revert ERC20BalanceReadFailed(asset, account);
        }
    }

    function _transferERC20(address asset, address payable recipient, uint256 amount) private {
        uint256 walletBefore = _erc20BalanceOf(asset, address(this));
        uint256 recipientBefore = _erc20BalanceOf(asset, recipient);
        uint256 expectedWalletBalance = walletBefore - amount;
        uint256 expectedRecipientBalance = recipientBefore + amount;

        bool success;
        uint256 transferResult;
        uint256 selector = uint32(IERC20.transfer.selector);
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, shl(224, selector))
            mstore(add(ptr, 0x04), recipient)
            mstore(add(ptr, 0x24), amount)
            success := call(gas(), asset, 0, ptr, 0x44, 0, 0)
            if iszero(and(success, eq(returndatasize(), 0x20))) { success := 0 }
            if success {
                returndatacopy(ptr, 0, 0x20)
                transferResult := mload(ptr)
            }
        }
        if (!success || transferResult != 1) {
            revert ERC20TransferFailed(asset, recipient, amount);
        }

        uint256 walletAfter = _erc20BalanceOf(asset, address(this));
        uint256 recipientAfter = _erc20BalanceOf(asset, recipient);
        if (walletAfter != expectedWalletBalance || recipientAfter != expectedRecipientBalance) {
            revert ERC20TransferInvariantBroken(
                asset,
                recipient,
                expectedWalletBalance,
                walletAfter,
                expectedRecipientBalance,
                recipientAfter
            );
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamSplitWallet.sol";
import "../../interfaces/stream/revenue/IStreamSplitWalletImplementation.sol";

/// @notice Fixed implementation deployment and version-4 deterministic clone bytecode.
/// @dev Public calls delegate into the factory: it remains the CREATE/CREATE2 origin.
/// Empty calldata stops without touching storage or calling implementation/recipient code.
/// Nonempty calldata uses the ERC-1167 delegate/return sequence with its jump relocated by 5.
library StreamSplitWalletDeployment {
    function deployImplementation() public returns (address) {
        return address(new StreamSplitWallet());
    }

    function runtimeCode(address implementation) internal pure returns (bytes memory) {
        return abi.encodePacked(
            hex"3615603257", // Empty calldata jumps to the final STOP at offset 0x32.
            hex"363d3d373d3d3d363d73",
            implementation,
            hex"5af43d82803e903d91603057fd5bf3", // Success JUMPDEST relocated to 0x30.
            hex"5b00"
        );
    }

    function initCode(address implementation) internal pure returns (bytes memory) {
        // Copy and return the exact 52-byte runtime, starting after this 10-byte prefix.
        return abi.encodePacked(hex"3d603480600a3d3981f3", runtimeCode(implementation));
    }

    function initCodeHash(address implementation) public pure returns (bytes32) {
        return keccak256(initCode(implementation));
    }

    function runtimeCodeHash(address implementation) public pure returns (bytes32) {
        return keccak256(runtimeCode(implementation));
    }

    function deploy(address implementation, bytes32 salt) public returns (address wallet) {
        bytes memory code = initCode(implementation);
        assembly ("memory-safe") {
            wallet := create2(0, add(code, 32), mload(code), salt)
        }
        if (wallet == address(0)) {
            revert IStreamSplitWalletImplementation.SplitWalletCloneDeploymentFailed(salt);
        }
    }
}

